from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MANIFEST = ROOT / "gold" / "holdouts.json"


def load_manifest() -> dict:
    return json.loads(MANIFEST.read_text(encoding="utf-8"))


def seed_ids() -> set[str]:
    return {row["episode_id"] for row in load_manifest()["seed"]}


def seed_paths() -> set[str]:
    return {row["gold_path"] for row in load_manifest()["seed"]}


def ci_ids() -> set[str]:
    return set(load_manifest()["ci"])


def sealed_ids() -> set[str]:
    return set(load_manifest()["sealed"])


def load_holdout_bodies(layer: str) -> list[dict]:
    if layer == "sealed":
        raise PermissionError("sealed holdouts are not readable in this repo or CI")
    if layer == "ci":
        raise FileNotFoundError("CI holdouts have no gold/turns bodies in this repo")
    if layer != "seed":
        raise ValueError(layer)
    turns = ROOT / "gold" / "turns"
    rows = []
    for rel in seed_paths():
        path = ROOT / rel
        with path.open(encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line:
                    rows.append(json.loads(line))
    return rows

import json
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools"))

from holdouts import ci_ids, load_holdout_bodies, sealed_ids, seed_ids, seed_paths  # noqa: E402

CATALOG = ROOT / "gold" / "catalog.jsonl"
GOLD_TURNS = ROOT / "gold" / "turns"
CONTEXT = ROOT / "plans" / "session" / "CONTEXT.md"
MANIFEST = ROOT / "gold" / "holdouts.json"


def _catalog():
    rows = []
    with CATALOG.open(encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if line:
                rows.append(json.loads(line))
    return rows


class HoldoutSplitTests(unittest.TestCase):
    def test_manifest_layers_are_disjoint(self):
        seed, ci, sealed = seed_ids(), ci_ids(), sealed_ids()
        self.assertEqual(len(seed), 8)
        self.assertTrue(ci)
        self.assertEqual(seed & ci, set())
        self.assertEqual(seed & sealed, set())
        self.assertEqual(ci & sealed, set())

    def test_seed_matches_gold_turns_on_disk(self):
        on_disk = {p.as_posix() for p in GOLD_TURNS.glob("*.jsonl")}
        rel = {f"gold/turns/{p.name}" for p in GOLD_TURNS.glob("*.jsonl")}
        self.assertEqual(rel, seed_paths())
        catalog_seed = {r["episode_id"] for r in _catalog() if r.get("gold_path")}
        self.assertEqual(catalog_seed, seed_ids())
        turn_eps = set()
        for path in GOLD_TURNS.glob("*.jsonl"):
            with path.open(encoding="utf-8") as fh:
                for line in fh:
                    if line.strip():
                        turn_eps.add(json.loads(line)["episode_id"])
        self.assertEqual(turn_eps, seed_ids())
        self.assertTrue(on_disk)

    def test_ci_ids_are_catalog_only_no_turn_files(self):
        by_id = {r["episode_id"]: r for r in _catalog()}
        for eid in ci_ids():
            self.assertIn(eid, by_id)
            self.assertTrue(by_id[eid].get("situation"))
            self.assertFalse(by_id[eid].get("gold_path"))
        with self.assertRaises(FileNotFoundError):
            load_holdout_bodies("ci")

    def test_ci_cannot_read_sealed(self):
        with self.assertRaises(PermissionError):
            load_holdout_bodies("sealed")
        for eid in sealed_ids():
            for path in GOLD_TURNS.glob("*.jsonl"):
                text = path.read_text(encoding="utf-8")
                self.assertNotIn(eid, text)

    def test_context_does_not_include_holdout_bodies(self):
        ctx = CONTEXT.read_text(encoding="utf-8")
        for eid in ci_ids() | sealed_ids():
            self.assertNotIn(eid, ctx)
        listed = [line.strip() for line in ctx.splitlines() if "gold/turns/" in line]
        for line in listed:
            self.assertTrue(any(p in line for p in seed_paths()))

    def test_manifest_schema_version(self):
        doc = json.loads(MANIFEST.read_text(encoding="utf-8"))
        self.assertEqual(doc["schema_version"], "1")
        self.assertEqual(doc["sealed"], [])

import unittest


class IsolationPropertyTests(unittest.TestCase):
    def test_memory_keyed_account_id_and_person_id(self):
        try:
            from hades_runtime.store import Store  # noqa: F401
        except ImportError:
            self.fail("no store: memory must be keyed account_id+person_id")

    def test_sister_track_cannot_read_partner_track(self):
        try:
            from hades_runtime.store import Store
        except ImportError:
            self.fail("no store: sister must not read partner-track facts")
        store = Store()
        store.write("acct-a", "person-partner", {"secret": "partner-track"})
        self.assertIsNone(store.read("acct-a", "person-sister", "secret"))

    def test_idle_does_not_page(self):
        try:
            from hades_runtime.idle import IdleWorker
        except ImportError:
            self.fail("no idle worker: default must not page primary_user")
        worker = IdleWorker()
        self.assertEqual(worker.tick()["outbound"], [])

    def test_day_one_chat_is_not_partner(self):
        try:
            from hades_runtime.register import select_register
        except ImportError:
            self.fail("no register select: flags only, day-one chat != partner")
        self.assertNotEqual(
            select_register(is_partner=False, is_family=False, chat_count=1),
            "partner",
        )

    def test_register_from_flags_not_display_name(self):
        try:
            from hades_runtime.register import select_register
        except ImportError:
            self.fail("no register select: display name is not identity")
        self.assertNotEqual(
            select_register(is_partner=False, is_family=True, display_name="wife"),
            "partner",
        )

