from pathlib import Path

def classify(root):
    hits=[]
    if not root.exists():
        return hits
    skip={'skills','tests','docs','docker','embeddings','.git','__pycache__','plugins'}
    for p in root.rglob('*'):
        if not p.is_file():
            continue
        parts=set(p.parts)
        if parts & skip or '__pycache__' in str(p):
            continue
        rel=p.relative_to(root).as_posix()
        n=p.name.lower()
        if p.suffix.lower() in {'.py','.md','.txt'} and n not in {'global.yaml'} :
            if not any(k in rel.lower() for k in ['state','neural','exist','thought','stor','growth','relation','career','cheat','daily_life','soul']):
                continue
        if p.suffix.lower() in {'.yaml','.yml','.json','.jsonl'} or 'stor' in rel.lower() or 'neural' in rel.lower() or 'growth' in rel.lower():
            hits.append((rel, p.stat().st_size))
    return hits

